//! 🧪️ Original finite actor caller pays resident ingress before any source byte donation.
mod original_wire{wasmtime::component::bindgen!({world:"actor",path:"../../../🧬️schema"});}
use semio_framework_plugin_guest_contract::original_actor_context::OriginalActorGuestEntry;
use semio_framework_actor::{OriginalActorInput,ActorGuestPhase,RetainedTurnInput};
use semio_framework_job::StepBudget;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress};
#[global_allocator]
static HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn clock()->Option<u64>{Some(100)}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(v,h)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(v,(h.requested_bytes,h.released_bytes))}
struct Lane{host:OriginalActorInput<()>,entry:OriginalActorGuestEntry,input:RetainedTurnInput,fuel:u64,work:u64,born:usize,released:usize}
impl Lane{
 fn new(law:&serde_json::Value)->Self{let root=&law["original"];let stock=&root["stock"];let grant=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let input=RetainedTurnInput{operation:root["operation"].as_u64().unwrap(),generation:root["generation"].as_u64().unwrap(),epoch:root["epoch"].as_u64().unwrap(),grant};Self{host:OriginalActorInput::new((),input).ok().unwrap(),entry:OriginalActorGuestEntry::new(),input,fuel:root["fuel"].as_u64().unwrap(),work:0,born:0,released:0}}
 fn receive(&mut self,input:RetainedTurnInput,spent:RetainedCloneProgress,work:u64,heap:(usize,usize),phase:ActorGuestPhase){assert_eq!(heap,(spent.retained_capacity_bytes,spent.released_bytes));self.born+=heap.0;self.released+=heap.1;self.fuel=self.fuel.checked_sub(work).unwrap();self.work+=work;self.host.receive_guest(input.return_original(spent).unwrap(),phase).unwrap();let returned=self.host.return_actor_turn().unwrap();self.input=RetainedTurnInput{epoch:self.input.epoch+1,grant:returned.remaining,..self.input};self.host.receive_next_issued(self.input).unwrap()}
}
#[test]
fn original_poll_input_pre_lift_denials_same_backing_partial_close_and_caller_conservation(){
 let page=original_wire::exports::semio::framework::reactor::PollInputPage{offset:0,length:64,word0:0x0706050403020100,word1:0x0f0e0d0c0b0a0908,word2:0x1716151413121110,word3:0x1f1e1d1c1b1a1918,word4:0x2726252423222120,word5:0x2f2e2d2c2b2a2928,word6:0x3736353433323130,word7:0x3f3e3d3c3b3a3938};let mut raw=[0u8;64];for(index,word)in[page.word0,page.word1,page.word2,page.word3,page.word4,page.word5,page.word6,page.word7].into_iter().enumerate(){raw[index*8..index*8+8].copy_from_slice(&word.to_le_bytes())}assert_eq!(raw,std::array::from_fn(|i|i as u8));assert_eq!(page.offset,0);assert_eq!(page.length,64);
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let mut lane=Lane::new(&law);let policy=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:1048576,maximum_release_bytes:1048576,maximum_depth:128};
 loop{let input=lane.host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||lane.entry.admit_step(input));let ready=call.result.unwrap().ready;lane.receive(input,call.receipt_spent,call.work_units_spent,heap,if ready{ActorGuestPhase::Ready}else{ActorGuestPhase::Pending});if ready{break}}
 for denial in [0,1,2,3]{let grant=match denial{0=>RetainedCloneGrant{maximum_items:0,..policy},1=>RetainedCloneGrant{maximum_depth:0,..policy},_=>policy};let Some(input)=lane.host.checkout_guest(grant).unwrap()else{assert!(!lane.entry.has_original_poll_input());continue};let budget=StepBudget::new(if denial==2{0}else{lane.fuel},if denial==3{100}else{1000},input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.reserve_poll_input_step(83,input,budget,&mut receipt,clock));assert!(!call.result.unwrap());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert!(!lane.entry.has_original_poll_input());lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched)}
 for phase in 0..2{if phase==1{let input=lane.host.checkout_guest(RetainedCloneGrant{maximum_capacity_bytes:82,..policy}).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.reserve_poll_input_step(83,input,budget,&mut receipt,clock));assert!(!call.result.unwrap());assert!(lane.entry.has_original_poll_input());assert!(lane.entry.with_original_poll_input(|_|()).is_none());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched)}let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.reserve_poll_input_step(83,input,budget,&mut receipt,clock));assert_eq!(call.result.unwrap(),phase==1);assert_eq!(call.work_units_spent,1);lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched)}
 let pointer=lane.entry.with_original_poll_input(|bytes|bytes.as_ptr()).unwrap();let bytes:[u8;83]=std::array::from_fn(|i|i as u8);
 for denial in 0..5{let grant=match denial{0=>RetainedCloneGrant{maximum_items:0,..policy},1=>RetainedCloneGrant{maximum_copy_bytes:63,..policy},2=>RetainedCloneGrant{maximum_depth:0,..policy},_=>policy};let Some(input)=lane.host.checkout_guest(grant).unwrap()else{assert_eq!(lane.entry.with_original_poll_input(|bytes|(bytes.as_ptr(),bytes.len())).unwrap(),(pointer,0));continue};let budget=StepBudget::new(if denial==3{0}else{lane.fuel},if denial==4{100}else{1000},input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.write_poll_input_words_step(0,64,[page.word0,page.word1,page.word2,page.word3,page.word4,page.word5,page.word6,page.word7],input,budget,&mut receipt,clock));assert!(!call.result.unwrap());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(lane.entry.with_original_poll_input(|bytes|(bytes.as_ptr(),bytes.len())).unwrap(),(pointer,0));lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched)}
 let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.write_poll_input_words_step(0,64,[page.word0,page.word1,page.word2,page.word3,page.word4,page.word5,page.word6,page.word7],input,budget,&mut receipt,clock));assert!(call.result.unwrap());assert_eq!(call.receipt_spent.copied_bytes,64);lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);assert_eq!(lane.entry.with_original_poll_input(|source|(source.as_ptr(),source.len(),source==&bytes[..64])).unwrap(),(pointer,64,true));
 let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.dispatch_value_step(input,budget,&mut receipt,clock,|cx|{let progress=cx.borrowed_original_cancel_token()?.signal_cancelled_flag_step(cx.retained_grant()).unwrap();cx.consume_retained(progress)?;cx.consume_fuel(1);Ok::<_,semio_framework_value::ValueError>(())}));assert!(call.result.is_ok());lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);
 let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.write_poll_input_step(64,&bytes[64..],input,budget,&mut receipt,clock));assert!(!call.result.unwrap());assert_eq!(call.receipt_spent,Default::default());assert_eq!(call.work_units_spent,0);assert_eq!(lane.entry.with_original_poll_input(|source|(source.as_ptr(),source.len())).unwrap(),(pointer,64));lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);
 let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.close_poll_input_step(input,budget,&mut receipt,clock));assert!(!call.result.unwrap());lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);
 for turn in 0..10000{if !lane.entry.has_original_poll_input(){break}let input=lane.host.checkout_guest(policy).unwrap().unwrap();let budget=StepBudget::new(lane.fuel,1000,input.grant);let mut receipt=Default::default();let(call,heap)=observe(||lane.entry.close_poll_input_step(input,budget,&mut receipt,clock));assert!(call.result.is_ok());lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);assert!(turn<9999)}
 for turn in 0..10000{if lane.entry.terminal_is_empty(){break}let input=lane.host.checkout_guest(policy).unwrap().unwrap();let(call,heap)=observe(||lane.entry.close_step(input));assert!(call.result.is_ok());lane.receive(input,call.receipt_spent,call.work_units_spent,heap,ActorGuestPhase::Dispatched);assert!(turn<9999)}assert_eq!(lane.born,lane.released);assert_eq!(lane.fuel+lane.work,65536);assert_eq!(observe(||drop(lane.entry)).1,(0,0));assert_eq!(lane.host.take_dispatched_input().unwrap(),Some(()));assert_eq!(observe(||drop(lane.host)).1,(0,0));
}
